def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    positions = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                positions.setdefault(v, []).append((r, c))

    def bounds(cells):
        return (min(r for r, c in cells), max(r for r, c in cells),
                min(c for r, c in cells), max(c for r, c in cells))

    mask_color = None
    for color, cells in positions.items():
        others = [p for v, ps in positions.items() if v != color for p in ps]
        if not others:
            continue
        r0, r1, c0, c1 = bounds(cells)
        a0, a1, b0, b1 = bounds(others)
        if r1 < a0 or a1 < r0 or c1 < b0 or b1 < c0:
            mask_color = color
            break

    mask = positions[mask_color]
    mr0, mr1, mc0, mc1 = bounds(mask)
    mask_set = set(mask)

    source = [p for color, cells in positions.items() if color != mask_color
              for p in cells]
    sr0, sr1, sc0, sc1 = bounds(source)
    tile = [row[sc0:sc1 + 1] for row in grid[sr0:sr1 + 1]]
    th, tw = len(tile), len(tile[0])

    mh, mw = mr1 - mr0 + 1, mc1 - mc0 + 1
    out = [[bg] * (mw * tw) for _ in range(mh * th)]
    for r in range(mh):
        for c in range(mw):
            if (mr0 + r, mc0 + c) in mask_set:
                for i in range(th):
                    for j in range(tw):
                        out[r * th + i][c * tw + j] = tile[i][j]
    return out
